const t0 = performance.now();
function findSeed(obsPosX, obsPosY) {
  for (let s = 0; s < 500000; s++) {
    let a = (s + 0x6d2b79f5) >>> 0;
    let t = Math.imul(a ^ (a >>> 15), a | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    const r1 = ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    const ox = -2.1 - 0.045 + 0.09 * r1;
    if (Math.abs(ox - obsPosX) > 0.0016) continue;
    let b = ((s ^ 0xa5a5a5a5) >>> 0);
    let sum = -1.5;
    for (let i = 0; i < 3; i++) {
      b = (b + 0x6d2b79f5) >>> 0;
      let u = Math.imul(b ^ (b >>> 15), b | 1);
      u ^= u + Math.imul(u ^ (u >>> 7), u | 61);
      sum += ((u ^ (u >>> 14)) >>> 0) / 4294967296;
    }
    if (ox + sum * 0.001 === obsPosX) return s;
  }
